SET auto_explain.log_min_duration = -1;
SET statement_timeout = '900s';
\timing on
\echo '--- E2A heute (alice, tags.listAll)'
EXPLAIN (ANALYZE, BUFFERS) SELECT "o"."id", "o"."name", "o"."match", "o"."matching_algorithm", "o"."is_insensitive", "o"."owner_id", "o"."color", "o"."is_inbox_tag", "o"."tn_parent_id", "o"."tn_priority", "o"."tn_ancestors_pks", "o"."tn_ancestors_count", "o"."tn_children_pks", "o"."tn_children_count", "o"."tn_depth", "o"."tn_descendants_pks", "o"."tn_descendants_count", "o"."tn_index", "o"."tn_level", "o"."tn_order", "o"."tn_siblings_pks", "o"."tn_siblings_count", (SELECT COUNT(DISTINCT "dt"."document_id") FROM "documents_document_tags" AS "dt" WHERE "dt"."tag_id" = "o"."id" AND "dt"."document_id" IN (SELECT "pl_authz_obj"."id" FROM "documents_document" AS "pl_authz_obj" LEFT JOIN "documents_document" AS "pl_authz_parent" ON "pl_authz_parent"."id" = "pl_authz_obj"."root_document_id" WHERE "pl_authz_obj"."deleted_at" IS NULL AND ((CASE WHEN ("pl_authz_obj"."root_document_id" IS NULL) THEN "pl_authz_obj"."owner_id" ELSE "pl_authz_parent"."owner_id" END) = '3' OR (CASE WHEN ("pl_authz_obj"."root_document_id" IS NULL) THEN "pl_authz_obj"."owner_id" ELSE "pl_authz_parent"."owner_id" END) IS NULL OR CAST(COALESCE("pl_authz_obj"."root_document_id", "pl_authz_obj"."id") AS varchar) IN (SELECT "object_pk" FROM "guardian_userobjectpermission" WHERE "user_id" = '3' AND "permission_id" IN (SELECT "id" FROM "auth_permission" WHERE "codename" = 'view_document' AND "content_type_id" IN (SELECT "id" FROM "django_content_type" WHERE "app_label" = 'documents' AND "model" = 'document')) UNION ALL (SELECT "object_pk" FROM "guardian_groupobjectpermission" WHERE "group_id" IN (SELECT "group_id" FROM "auth_user_groups" WHERE "user_id" = '3') AND "permission_id" IN (SELECT "id" FROM "auth_permission" WHERE "codename" = 'view_document' AND "content_type_id" IN (SELECT "id" FROM "django_content_type" WHERE "app_label" = 'documents' AND "model" = 'document'))))))) AS "document_count" FROM "documents_tag" AS "o" WHERE "o"."id" IN (SELECT "pl_authz_obj"."id" FROM "documents_tag" AS "pl_authz_obj" WHERE "pl_authz_obj"."owner_id" = '3' OR "pl_authz_obj"."owner_id" IS NULL OR CAST("pl_authz_obj"."id" AS varchar) IN (SELECT "object_pk" FROM "guardian_userobjectpermission" WHERE "user_id" = '3' AND "permission_id" IN (SELECT "id" FROM "auth_permission" WHERE "codename" = 'view_tag' AND "content_type_id" IN (SELECT "id" FROM "django_content_type" WHERE "app_label" = 'documents' AND "model" = 'tag')) UNION ALL (SELECT "object_pk" FROM "guardian_groupobjectpermission" WHERE "group_id" IN (SELECT "group_id" FROM "auth_user_groups" WHERE "user_id" = '3') AND "permission_id" IN (SELECT "id" FROM "auth_permission" WHERE "codename" = 'view_tag' AND "content_type_id" IN (SELECT "id" FROM "django_content_type" WHERE "app_label" = 'documents' AND "model" = 'tag'))))) ORDER BY LOWER(o.name) ASC;
\echo '--- E2B Vorschlag GROUP BY'
EXPLAIN (ANALYZE, BUFFERS) SELECT "o"."id", "o"."name", "o"."match", "o"."matching_algorithm", "o"."is_insensitive", "o"."owner_id", "o"."color", "o"."is_inbox_tag", "o"."tn_parent_id", "o"."tn_priority", "o"."tn_ancestors_pks", "o"."tn_ancestors_count", "o"."tn_children_pks", "o"."tn_children_count", "o"."tn_depth", "o"."tn_descendants_pks", "o"."tn_descendants_count", "o"."tn_index", "o"."tn_level", "o"."tn_order", "o"."tn_siblings_pks", "o"."tn_siblings_count", COALESCE("c"."n", 0) AS "document_count" FROM "documents_tag" AS "o" LEFT JOIN (SELECT "dt"."tag_id" AS "k", COUNT(DISTINCT "dt"."document_id") AS "n" FROM "documents_document_tags" AS "dt" WHERE "dt"."document_id" IN (SELECT "pl_authz_obj"."id" FROM "documents_document" AS "pl_authz_obj" LEFT JOIN "documents_document" AS "pl_authz_parent" ON "pl_authz_parent"."id" = "pl_authz_obj"."root_document_id" WHERE "pl_authz_obj"."deleted_at" IS NULL AND ((CASE WHEN ("pl_authz_obj"."root_document_id" IS NULL) THEN "pl_authz_obj"."owner_id" ELSE "pl_authz_parent"."owner_id" END) = '3' OR (CASE WHEN ("pl_authz_obj"."root_document_id" IS NULL) THEN "pl_authz_obj"."owner_id" ELSE "pl_authz_parent"."owner_id" END) IS NULL OR CAST(COALESCE("pl_authz_obj"."root_document_id", "pl_authz_obj"."id") AS varchar) IN (SELECT "object_pk" FROM "guardian_userobjectpermission" WHERE "user_id" = '3' AND "permission_id" IN (SELECT "id" FROM "auth_permission" WHERE "codename" = 'view_document' AND "content_type_id" IN (SELECT "id" FROM "django_content_type" WHERE "app_label" = 'documents' AND "model" = 'document')) UNION ALL (SELECT "object_pk" FROM "guardian_groupobjectpermission" WHERE "group_id" IN (SELECT "group_id" FROM "auth_user_groups" WHERE "user_id" = '3') AND "permission_id" IN (SELECT "id" FROM "auth_permission" WHERE "codename" = 'view_document' AND "content_type_id" IN (SELECT "id" FROM "django_content_type" WHERE "app_label" = 'documents' AND "model" = 'document')))))) GROUP BY 1) AS "c" ON "c"."k" = "o"."id" WHERE "o"."id" IN (SELECT "pl_authz_obj"."id" FROM "documents_tag" AS "pl_authz_obj" WHERE "pl_authz_obj"."owner_id" = '3' OR "pl_authz_obj"."owner_id" IS NULL OR CAST("pl_authz_obj"."id" AS varchar) IN (SELECT "object_pk" FROM "guardian_userobjectpermission" WHERE "user_id" = '3' AND "permission_id" IN (SELECT "id" FROM "auth_permission" WHERE "codename" = 'view_tag' AND "content_type_id" IN (SELECT "id" FROM "django_content_type" WHERE "app_label" = 'documents' AND "model" = 'tag')) UNION ALL (SELECT "object_pk" FROM "guardian_groupobjectpermission" WHERE "group_id" IN (SELECT "group_id" FROM "auth_user_groups" WHERE "user_id" = '3') AND "permission_id" IN (SELECT "id" FROM "auth_permission" WHERE "codename" = 'view_tag' AND "content_type_id" IN (SELECT "id" FROM "django_content_type" WHERE "app_label" = 'documents' AND "model" = 'tag'))))) ORDER BY LOWER(o.name) ASC;
